window.FeelingsVocabulary = [
  {word:'ugly', image:"data:image/png;base64,"},
  {word:'sad', image:"data:image/png;base64,"},
  {word:'beautiful', image:"data:image/png;base64,"},
  {word:'old', image:"data:image/png;base64,"},
  {word:'happy', image:"data:image/png;base64,"},
  {word:'young', image:"data:image/png;base64,"}
];
(() => {
const $=id=>document.getElementById(id);
const cards=window.FeelingsVocabulary.flatMap((v,pair)=>[{id:pair*2,pair,type:'word',word:v.word},{id:pair*2+1,pair,type:'image',word:v.word,image:v.image}]);
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function fresh(){return {deck:shuffle(cards.map(c=>c.id)),open:[],matched:[],moves:0,results:[],lastAction:'',startedAt:Date.now()}}
let state=fresh(),timer=null;
function publish(){window.ClassroomBridge.publish()}
function settle(){clearTimeout(timer);if(state.open.length!==2)return;const a=cards[state.open[0]],b=cards[state.open[1]];timer=setTimeout(()=>{if(a.pair===b.pair)state.matched.push(a.pair);state.open=[];render();publish()},a.pair===b.pair?350:850)}
function openCard(id){
const card=cards[id];if(state.open.length===2||state.open.includes(id)||state.matched.includes(card.pair))return;
state.open.push(id);state.lastAction=`Opened ${card.type}: ${card.word}`;
if(state.open.length===2){state.moves++;const a=cards[state.open[0]],b=cards[state.open[1]],isCorrect=a.pair===b.pair&&a.type!==b.type;state.results.push({question:'Match word and picture',studentAnswer:`${a.word} (${a.type}) + ${b.word} (${b.type})`,correctAnswer:`${a.word}: word + picture`,isCorrect});state.lastAction=`${a.word} + ${b.word}: ${isCorrect?'match':'try again'}`}
render();publish();settle();
}
function render(){
$('board').replaceChildren();
state.deck.forEach(id=>{const item=cards[id],card=document.createElement('button');card.type='button';card.className='card'+(state.open.includes(id)?' open':'')+(state.matched.includes(item.pair)?' matched':'');card.dataset.pair=item.pair;card.dataset.type=item.type;card.setAttribute('aria-label',state.open.includes(id)||state.matched.includes(item.pair)?`${item.type}: ${item.word}`:'Hidden card');card.disabled=state.matched.includes(item.pair);card.innerHTML=`<div class="inner"><div class="face front"></div><div class="face back">${item.type==='word'?`<div class="word">${item.word}</div>`:`<img class="pic" src="${item.image}" alt="">`}</div></div>`;card.onclick=()=>openCard(id);$('board').append(card)});
$('moves').textContent='Moves: '+state.moves;$('pairs').textContent='Pairs: '+state.matched.length+' / 6';$('finish').classList.toggle('show',state.matched.length===6);
}
function restart(){clearTimeout(timer);const results=state.results;state={...fresh(),results,lastAction:'Restarted game'};render();publish()}
$('restartBtn').onclick=restart;$('playAgain').onclick=restart;render();
window.ClassroomBridge.init({restore(saved){if(saved&&Array.isArray(saved.deck)&&saved.deck.length===12&&new Set(saved.deck).size===12&&saved.deck.every(n=>Number.isInteger(n)&&n>=0&&n<12)&&Array.isArray(saved.open)&&saved.open.length<=2&&new Set(saved.open).size===saved.open.length&&saved.open.every(n=>saved.deck.includes(n))&&Array.isArray(saved.matched)&&new Set(saved.matched).size===saved.matched.length&&saved.matched.every(n=>Number.isInteger(n)&&n>=0&&n<6)&&Array.isArray(saved.results)&&Number.isInteger(saved.moves)&&saved.moves>=0)state=saved;render();settle()},snapshot(){return {state,details:{source:'feelings-memory',activityTitle:'Feelings — Word + Picture Memory',openCards:state.open.map(id=>({word:cards[id].word,type:cards[id].type})),matchedWords:state.matched.map(pair=>window.FeelingsVocabulary[pair].word),completedCount:state.matched.length,moves:state.moves,mistakes:state.results.filter(r=>!r.isCorrect).length,lastAction:state.lastAction,results:state.results,score:state.matched.length,total:6,status:state.matched.length===6?'completed':'in_progress',timeSeconds:Math.round((Date.now()-state.startedAt)/1000)}}}});
})();
